The BMP280 and ESP32 must share ground. Because this breakout is specified for 3.3 V operation and its I2C pull-ups are already present, do not add another set of pull-up resistors.

I2C uses two shared open-drain signal lines. SDA carries bidirectional data, while SCL is the clock line driven by the I2C controller during normal ESP32 master operation. Devices pull these lines LOW and the pull-up resistors return them HIGH. With the module powered and pulled up to 3.3 V, the HIGH level remains compatible with ESP32 GPIO, which is not 5 V tolerant.

```cpp
#include <Wire.h>
#include <Adafruit_BMP280.h>

Adafruit_BMP280 bmp;

const int SDA_PIN = 21;
const int SCL_PIN = 22;

void setup() {
  Serial.begin(115200);

  Wire.begin(SDA_PIN, SCL_PIN);

  if (!bmp.begin(0x76)) {
    Serial.println("BMP280 not found at I2C address 0x76");
    while (true) {
      delay(1000);
    }
  }
}

void loop() {
  float temperatureC = bmp.readTemperature();
  float pressureHpa = bmp.readPressure() / 100.0f;

  Serial.print("Temperature: ");
  Serial.print(temperatureC);
  Serial.print(" C, Pressure: ");
  Serial.print(pressureHpa);
  Serial.println(" hPa");

  delay(1000);
}
```

`readPressure()` returns pressure in pascals, so dividing by 100 converts Pa to hPa. If the device is not found, first check power, common ground, SDA/SCL placement, and the stated 0x76 address before changing application logic.

